function acceptDays(days) {
  return Number.isInteger(days) && days >= 1 && days <= 21;
}

function allowedDays(extended) {
  let days = 7; // S1
  if (extended) { // D1
    days = 21; // S2
  }
  return days; // S3
}

// 결함이 있던 조건
const before = days => Number.isInteger(days) && days >= 1 && days < 21;
// 수정한 조건: 합의한 상한을 포함한다
const after = days => Number.isInteger(days) && days >= 1 && days <= 21;

// 교육용 가정: JSON 파싱이 끝난 대출 옵션만 검사한다.
// 실제 서버 요청 처리·파싱·권한 검사는 구현하지 않는다.
function acceptsLoanOptions(value) {
  if (
    value === null
    || typeof value !== "object"
    || Array.isArray(value)
  ) {
    return false;
  }
  const keys = Object.keys(value);
  if (
    keys.length !== 2
    || !keys.every(key => key === "loanDays" || key === "pickup")
  ) {
    return false;
  }
  return typeof value.loanDays === "number"
    && Number.isInteger(value.loanDays)
    && value.loanDays >= 1 && value.loanDays <= 21
    && ["desk", "locker"].includes(value.pickup);
}

function traceReservation(mode, trace) {
  try {
    trace.push("try");
    if (mode === "full") {
      throw new RangeError("full");
    }
    if (mode === "broken") {
      throw new TypeError("broken");
    }
    trace.push("accepted");
  } catch (error) {
    trace.push("catch");
    if (!(error instanceof RangeError)) {
      throw error;
    }
    trace.push("handled");
  } finally {
    trace.push("finally");
  }
  trace.push("after");
  return "completed";
}
